    static void tick(){
        var mc=mc();if(mc.player==null||mc.level==null||mc.getSingleplayerServer()==null||mc.getOverlay()!=null)return;
        check(mc.getSingleplayerServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).toAbsolutePath().normalize().getFileName().toString().equals(Boolean.getBoolean("wg.ordinaryAudit")?"wg-ordinary-audit":"wg-gameplay-audit"),"Gameplay audit requires its disposable save");
        check(!mc.player.isDeadOrDying(),"Gameplay audit player died before step "+current);if(failure!=null)throw new IllegalStateException("Gameplay audit server failure",failure);if(steps.isEmpty()){if(Boolean.getBoolean("wg.ordinaryAudit"))OrdinaryAuditClient.plan();else plan();}if(current>=steps.size())return;var step=steps.get(current);ticks++;phaseTicks++;
        if(phase==0){prepared=false;verified=false;expectedHeld=null;phaseTicks=0;phase=1;System.out.println((Boolean.getBoolean("wg.ordinaryAudit")?"WG_PORT8_STEP: ":"WG_PORT6_STEP: ")+current+" "+step.name());server(p->{step.prepare().accept(p);prepared=true;});}
        else if(phase==1&&prepared&&phaseTicks>=8){var expected=expectedHeld;if(expected!=null&&!expected.isEmpty()&&(!ItemStack.isSameItem(mc.player.getMainHandItem(),expected)||mc.player.getMainHandItem().getCount()!=expected.getCount())){check(phaseTicks<200,"inventory fixture never reached client for "+step.name()+" expected="+expected+" actual="+mc.player.getMainHandItem());return;}step.action().run();phase=2;phaseTicks=0;}
        else if(phase==2&&phaseTicks>=16){phase=3;server(p->{step.verify().accept(p);verified=true;});}
        else if(phase==3&&verified){current++;phase=0;phaseTicks=0;}
    }
